cssCode:
.ring-wrap {
  perspective: 800px; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.text-ring {
  transform-style: preserve-3d;
  animation: rotateRing 10s infinite linear;
  position: relative;
}
.ring-char {
  position: absolute; font-size: 30px; font-weight: bold;
  font-family: sans-serif; color: #ff007f;
  text-shadow: 0 0 15px #ff007f;
  transform-origin: center;
}
@keyframes rotateRing { 100% { transform: rotateY(-360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'ring-wrap';

const ring = document.createElement('div');
ring.className = 'text-ring';

const text = "ULTRA MAX PREMIUM PRO SUPER ANIMATION ";
const chars = text.split('');
const radius = 150;
const deg = 360 / chars.length;

chars.forEach((char, i) => {
  const span = document.createElement('span');
  span.className = 'ring-char';
  span.innerText = char;
  // Position each character in a 3D circle
  span.style.transform = `rotateY(${i * deg}deg) translateZ(${radius}px)`;
  ring.appendChild(span);
});

wrap.appendChild(ring);
c.appendChild(wrap);
